import React, { useState } from "react";

export default function Login({ onRegisterClick }) {
  const [form, setForm] = useState({
    identifier: "",
    password: "",
  });

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    setTimeout(() => {
      if (!form.identifier || !form.password) {
        setError("Please enter your email or mobile number and password.");
      } else {
        alert("Login form submitted successfully!");
      }
      setLoading(false);
    }, 800);
  };

  const handleRegisterClick = () => {
    if (onRegisterClick) {
      onRegisterClick();
    }
  };

  return (
    <div style={styles.wrapper}>
      <form style={styles.card} onSubmit={handleSubmit}>
        <div style={styles.header}>
          <h2 style={styles.heading}>Welcome Back!</h2>
          <p style={styles.subText}>Login to continue your journey</p>
        </div>

        {error && <div style={styles.error}>{error}</div>}

        <label style={styles.label}>Email or Mobile Number</label>
        <input
          style={styles.input}
          type="text"
          name="identifier"
          placeholder="Enter your email or mobile number"
          value={form.identifier}
          onChange={handleChange}
          required
        />

        <label style={styles.label}>Password</label>
        <input
          style={styles.input}
          type="password"
          name="password"
          placeholder="Enter your password"
          value={form.password}
          onChange={handleChange}
          required
        />

        <div style={styles.buttonRow}>
          <button style={styles.button} type="submit" disabled={loading}>
            {loading ? "Logging in..." : "Login"}
          </button>

          <button style={styles.registerButton} type="button" onClick={handleRegisterClick}>
            Register
          </button>
        </div>
      </form>
    </div>
  );
}

const styles = {
  wrapper: {
    display: "flex",
    justifyContent: "center",
    paddingTop: "60px",
  },
  card: {
    background: "#fff",
    padding: "32px",
    borderRadius: "12px",
    boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
    width: "100%",
    maxWidth: "380px",
    display: "flex",
    flexDirection: "column",
    gap: "8px",
  },
  header: {
    textAlign: "center",
    marginBottom: "8px",
  },
  heading: {
    margin: "0 0 4px",
    fontSize: "24px",
    color: "#1b1f3b",
  },
  subText: {
    margin: 0,
    fontSize: "14px",
    color: "#666",
  },
  label: { fontSize: "13px", color: "#555", marginTop: "8px" },
  input: {
    padding: "10px",
    borderRadius: "6px",
    border: "1px solid #ccc",
    fontSize: "15px",
  },
  buttonRow: {
    display: "flex",
    gap: "10px",
    marginTop: "16px",
  },
  button: {
    flex: 1,
    padding: "12px",
    borderRadius: "6px",
    border: "none",
    background: "#1b1f3b",
    color: "#fff",
    fontWeight: "bold",
    cursor: "pointer",
  },
  registerButton: {
    flex: 1,
    padding: "12px",
    borderRadius: "6px",
    border: "1px solid #1b1f3b",
    background: "#fff",
    color: "#1b1f3b",
    fontWeight: "bold",
    cursor: "pointer",
  },
  error: {
    background: "#ffe5e5",
    color: "#c0392b",
    padding: "10px",
    borderRadius: "6px",
    fontSize: "14px",
  },
};
